-- ============================================================================
-- FC7: Produced Water Treatment joins the catalog, the SEVENTH Facilities course.
--
-- Catalog row (module 'facilities'; path_order 45, directly above FC6
-- heattransfer at 44, FC5 at 43, FC4 gasprocessing at 42, FC3 rotating at 41,
-- FC2 linesizing at 40 and FC1 separation at 39; prereq_slug NULL, the
-- carried-over answer "no hard prerequisite inside a module") plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/producedwater/gen_course.py from fields.json,
-- precision.json and the capstone constants in fc7_fields_capstone.mjs, which
-- are read by node and never retyped. Deep seeds are three separate migrations;
-- the go-live is a fifth and is HELD until a NextGen production upload carries
-- the route /dashboard/apps/producedwater, because the 78 lessons, the teaching
-- lab (producedWaterLab.js) and its three explorer panels ship in the zip and
-- not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. Oil in water is a droplet size distribution
-- and not a concentration, every cut size is computed from the equipment and the
-- fluids, and a train carries the OUTLET distribution forward, so the next
-- device faces finer water than its own cut size suggests.
--
-- THE ENGINE. engines/facilities/producedWater.js (the water viscosity and the
-- brine and crude densities, the log-normal droplet grid and its interpolated
-- volume median, Stokes and the full drag balance, the API 421 basin, the plate
-- pack, the hydrocyclone on stated geometry with its operating envelope and
-- shear penalty, flotation as attachment kinetics, the media bed as inverted
-- depth filtration, and the train). It imports nothing. Vendored at engines
-- 9874d58, the FC7-1 repair, sha-identical over a walked import closure.
--
-- NOTHING GRADED DEPENDS ON A HELD QUANTITY, and each is neutralised by
-- CONSTRUCTION. No graded field reads a flotation cut, which is the one answer
-- the calibration reaches: IZOMBE grades the bubble rise and the holdup, and the
-- capstone generator moves the attachment efficiency tenfold and asserts both
-- stay identical to the last bit. Both graded beds are packed at the module's
-- own reference grain of 800 micron, where the held inverse-cube exponent
-- multiplies by exactly one. TUNU is given no dissolved oil floor and no
-- specification, so no graded concentration is floored and no graded field is a
-- verdict. OGULAGHA's basin sits under the fixed horizontal velocity limit, so
-- the missing half of that rule decides nothing. Every pinned constant a graded
-- answer reads is stated on the capstone page.
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: the fluid
-- properties a cut stands on, that a basin cut is a surface loading inverted,
-- that a liner bank run short of liners is at the ceiling and carries a
-- penalty, that a bubble rises by the full drag balance and sets a holdup, that
-- a bed cut is depth filtration read backwards, and that in a train every stage
-- works on the water the stage before it left.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('producedwater', 'Produced Water Treatment', 'facilities', 45, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'producedwater', 'beginner', 'associate',
  'OGULAGHA, a produced water stream read from its fluids to a basin and a plate pack',
  'The water, the oil and the gravity front end',
  'OGULAGHA, a gravity front end on a warm, moderately saline field. The water is 36000 bwpd, taken to m3/s with the exact barrel of 0.158987294928 m3, at 58.5 C and 42500 ppm of total dissolved solids, and the crude is 27.5 degrees API at the same temperature. The droplets arrive at 420 ppm with a volume median of 22 micron and a log spread sigma of 0.75. The basin is 15 m long, 3.4 m wide and 1.5 m deep, read at a short-circuit allowance F of 1.6. The plate pack is 48 plates of 2.5 m2 projected area each, with 0.7 of that area credited as settling. The water viscosity fit, the brine density fit and the crude density chain from API gravity are the module''s own declared choices, and nothing else is looked up. Report six values: the water viscosity, the brine density, the crude density, the Stokes rise velocity of a droplet at the volume median, the basin cut size and the plate pack cut size. The viscosity in Pa.s and the rise velocity in m/s, to twelve decimals. The two densities in kg/m3 and the two cut sizes in micron, to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogulagha_water_viscosity_pas', 'label','The water viscosity at the stream temperature and salinity', 'unit','Pa.s', 'expected',0.0005101915934473397, 'tol',1e-12),
    jsonb_build_object('key','ogulagha_water_density_kgm3', 'label','The brine density at the stream temperature and salinity', 'unit','kg/m3', 'expected',1013.7286105037547, 'tol',0.0001),
    jsonb_build_object('key','ogulagha_oil_density_kgm3', 'label','The crude density at the stream temperature', 'unit','kg/m3', 'expected',862.3241899811321, 'tol',0.0001),
    jsonb_build_object('key','ogulagha_droplet_rise_ms', 'label','The Stokes rise velocity of the median droplet', 'unit','m/s', 'expected',7.82526023252317e-05, 'tol',1e-10),
    jsonb_build_object('key','ogulagha_basin_cut_micron', 'label','The API 421 basin cut size', 'unit','micron', 'expected',113.37669131197052, 'tol',1e-06),
    jsonb_build_object('key','ogulagha_plate_cut_micron', 'label','The plate pack cut size', 'unit','micron', 'expected',69.84080434958841, 'tol',1e-06)
  )
),
(
  'producedwater', 'intermediate', 'professional',
  'IZOMBE, a liner bank run short of liners, a flotation unit and a media bed on one water',
  'The three devices whose cut does not come from gravity alone',
  'IZOMBE, three de-oiling devices on a cooler, much more saline field. The water is 58000 bwpd, taken to m3/s with the exact barrel of 0.158987294928 m3, at 47 C and 88000 ppm of total dissolved solids, and the crude is 31 degrees API at the same temperature. The liner bank is 100 liners, each of 0.035 m bore and 0.7 m length, rated at 0.0006 m3/s and 1000 g at that flow, with the oil core taken at 0.5 of the liner radius. The flotation unit is 3 cells of 26 m3, 3.5 m deep, fed gas at 0.12 times the water flow to each cell as bubbles of 220 micron with a gas density of 1.2 kg/m3. The media bed is 18 m2 and 1.1 m deep, packed at 800 micron, with a filter coefficient of 3.5 per m declared at a 20 micron droplet. The operating envelope of a liner, the drag coefficient a bubble rises against and the loading dependence of the bed are the module''s own declared choices. Report six values: the turndown the liners run at, the inlet shear penalty on their cut, the liner bank cut size, the rise velocity of one bubble, the gas holdup of the swarm and the bed cut size. The turndown, the shear penalty and the holdup as ratios and the two cut sizes in micron, to six decimals. The rise velocity in m/s, to twelve decimals.',
  jsonb_build_array(
    jsonb_build_object('key','izombe_liner_turndown_ratio', 'label','The turndown the liners run at', 'unit','ratio', 'expected',1.7787930373888892, 'tol',5e-07),
    jsonb_build_object('key','izombe_cyclone_shear_penalty', 'label','The inlet shear penalty on the liner cut', 'unit','ratio', 'expected',1.1697445603434073, 'tol',5e-07),
    jsonb_build_object('key','izombe_cyclone_cut_micron', 'label','The liner bank cut size, with its penalty applied', 'unit','micron', 'expected',5.319865594518567, 'tol',1e-06),
    jsonb_build_object('key','izombe_bubble_rise_ms', 'label','The full drag balance rise velocity of one bubble', 'unit','m/s', 'expected',0.02505191646373671, 'tol',1e-10),
    jsonb_build_object('key','izombe_gas_holdup_ratio', 'label','The gas holdup of the swarm', 'unit','ratio', 'expected',0.06881952310620194, 'tol',5e-07),
    jsonb_build_object('key','izombe_filter_cut_micron', 'label','The media bed cut size', 'unit','micron', 'expected',10.257441012720951, 'tol',1e-06)
  )
),
(
  'producedwater', 'advanced', 'expert',
  'TUNU, a three stage train read stage by stage and at its outlet',
  'The coupling, and a droplet outside the band',
  'TUNU, a three stage train on a hot, fresher field. The water is 44000 bwpd, taken to m3/s with the exact barrel of 0.158987294928 m3, at 66 C and 21000 ppm of total dissolved solids, and the crude is 36 degrees API at the same temperature. The inlet carries 1150 ppm of oil at a volume median of 19 micron and a log spread sigma of 0.85, described on 60 bins spanning 4 sigma either side of the median. The train runs in this order: a plate pack of 56 plates of 2.2 m2 with 0.7 of the projected area credited as settling; then a liner bank of 120 liners, each of 0.035 m bore and 0.7 m length, rated at 0.0006 m3/s and 1000 g at that flow, with the oil core taken at 0.5 of the liner radius; then a media bed of 14 m2 and 1.4 m deep, packed at 800 micron, with a filter coefficient of 3.5 per m declared at a 20 micron droplet. Every cut size is the engine''s own for its device, and no dissolved oil floor and no discharge specification is given. Report six values: the removal of the plate pack stage and of the liner bank stage, each as a percentage of the oil reaching it, the droplet median leaving the liner bank stage, the train outlet concentration, the droplet median leaving the train, and the Reynolds number the module reports for a 240 micron droplet in this water. Removals in percent, the concentration in ppm, the medians in micron and the Reynolds number as a ratio, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','tunu_cyclone_stage_median_micron', 'label','The droplet median leaving the liner bank stage', 'unit','micron', 'expected',4.693996003747812, 'tol',1e-06),
    jsonb_build_object('key','tunu_plate_stage_removal_pct', 'label','The plate pack stage removal, of the oil reaching it', 'unit','percent', 'expected',11.801201005213063, 'tol',1e-06),
    jsonb_build_object('key','tunu_cyclone_stage_removal_pct', 'label','The liner bank stage removal, of the oil reaching it', 'unit','percent', 'expected',93.8488534141062, 'tol',1e-06),
    jsonb_build_object('key','tunu_train_outlet_ppm', 'label','The train outlet concentration', 'unit','ppm', 'expected',45.682546314511974, 'tol',1e-06),
    jsonb_build_object('key','tunu_train_outlet_median_micron', 'label','The droplet median leaving the train', 'unit','micron', 'expected',4.08399589751163, 'tol',1e-06),
    jsonb_build_object('key','tunu_coarse_droplet_reynolds', 'label','The Reynolds number reported for the coarse droplet', 'unit','ratio', 'expected',6.997495185436383, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
